// Writes src/abi.ts from the Foundry build output. Run `forge build` in ../contracts first.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const artifact = JSON.parse(
  readFileSync(join(here, "../../contracts/out/PromoVault.sol/PromoVault.json"), "utf8"),
);

const out =
  "// Generated by scripts/gen-abi.mjs from contracts/out. Do not edit by hand: run `pnpm abi`.\n" +
  `export const promoVaultAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;

writeFileSync(join(here, "../src/abi.ts"), out);
console.log(`src/abi.ts written: ${artifact.abi.length} entries`);
